t,x,v,a=df['t'],df['x'],df['v'],df['dv_dt']
def fitcols(cols):
    X=np.column_stack(cols); c,_,_,_=np.linalg.lstsq(X,a,rcond=None); r=a-X@c
    return np.var(r)/np.var(a), c
