    for name,g in [('poly',[x,x**2,x**3]),('inv',[1/x,x,x*x]),('sqrt',[np.sqrt(x),x,x*x]),('x15',[x**1.5,x,x*x])]:
        cols=base+[C,S]+[h*C for h in g]+[h*S for h in g]
